import { createHash } from 'node:crypto';
import { businessTypes } from './constants';
import { businessTypeLabel } from './business-type-label';
import { REGISTRATION_STEPS } from './registration-flow';
import { LISTING_PUBLISH_REQUIREMENT, REGISTER_PHOTO_REQUIREMENT } from './register-photo-policy';
import { LISTING_FEES_NOTICE } from './public-listing-terms';
import { listingEvidenceOptions } from './listing-verification-evidence';

/** Public facts only. Generated by the running application, never by a model. */
export function lineSupportKnowledge(deployment: string | null) {
  const facts = {
    pricing: LISTING_FEES_NOTICE,
    industries: businessTypes.filter(value => value !== 'その他').map(businessTypeLabel),
    registration: REGISTRATION_STEPS.map(step => `${step.title}：${step.detail}`),
    registrationScope: '標準の掲載手順です。個別の書類提出条件は運営へご相談ください。',
    documentRequirement: REGISTRATION_STEPS.find(step => step.key === 'documents')?.detail ?? null,
    documentTiming: '掲載申込は書類が手元になくても先に送信できます。書類は申込とアカウント作成の後、公開前に提出します。',
    acceptedDocuments: listingEvidenceOptions.map(option => option.label),
    publication: LISTING_PUBLISH_REQUIREMENT,
    photos: REGISTER_PHOTO_REQUIREMENT,
    sources: ['https://carelink-jp.com/register', 'https://carelink-jp.com/register/guide', 'https://carelink-jp.com/terms'],
  };
  return {
    schema: 1 as const, deployment,
    revision: createHash('sha256').update(JSON.stringify(facts)).digest('hex'),
    facts,
  };
}
export type LineSupportKnowledge = ReturnType<typeof lineSupportKnowledge>;

const pricingSubject='(?:料金|掲載料|掲載費用|掲載料金|けいさいひよう|けいさいりょう|予約手数料)';
// Full-message grammar: greetings and spelling variants cannot admit a second request.
const naturalPricingQuestion=new RegExp(`^(?:${pricingSubject}について(?:教えて|おしえて)(?:ほしい|ほし)ん?です(?:けど|が|けれど))?${pricingSubject}(?:(?:は|が|って)?(?:いくら(?:ですか|かかりますか)?|かかりますか|無料ですか)|(?:を|について)?(?:教えて|おしえて)ください)$`);

export type PublicAnswer = { topic: string; text: string; knowledgeRevision: string };
/** Deliberately narrow: an unrecognised or compound request is a draft, not a guess. */
export function publicLineSupportAnswer(input: string, knowledge: LineSupportKnowledge): PublicAnswer | null {
  if (!knowledge.deployment || !/^[a-f0-9]{40}$/.test(knowledge.deployment)) return null;
  const text = input.normalize('NFKC').trim().replace(/[？?。！!、,\s]/g, '');
  const answer = (topic: string, body: string): PublicAnswer => ({ topic, text: body, knowledgeRevision: knowledge.revision });
  if (['料金について', '掲載料', '予約手数料', '掲載料は無料ですか', '料金はかかりますか'].includes(text)||naturalPricingQuestion.test(text)) {
    // Preserve the current published facts; only soften sentence endings for LINE.
    const pricing = knowledge.facts.pricing.replace(/無料です。/g, '無料となっております。').replace(/通知します。/g, 'お知らせいたします。');
    return answer('pricing', `お問い合わせありがとうございます。\nCareLinkの掲載費用についてご案内いたします。\n\n${pricing}\n\n詳しくは、こちらの利用規約をご確認ください。\nhttps://carelink-jp.com/terms\n\nご不明な点がございましたら、お気軽にお問い合わせください。`);
  }
  if (['掲載までの流れ', '登録方法', '登録方法を知りたい'].includes(text)) {
    return answer('registration', `${knowledge.facts.registrationScope}\n\n${knowledge.facts.registration.map((step, i) => `${i + 1}. ${step}`).join('\n')}\n\nhttps://carelink-jp.com/register/guide`);
  }
  // Document requirements can depend on a facility's verified/deferred state.
  // Public onboarding copy is insufficient to decide an individual exemption.
  if (['写真は必要ですか', '写真なしでも掲載できますか'].includes(text)) {
    return answer('photos', `${knowledge.facts.photos}\n\nhttps://carelink-jp.com/register/guide`);
  }
  const industry = knowledge.facts.industries.find(value => text === value || text === `${value}は掲載できますか`);
  if (industry) return answer('industry', `${industry}は、掲載申込の業種に含まれています。公開には店舗確認と必要な設定が必要です。\n\nhttps://carelink-jp.com/register`);
  return null;
}
